/* Prototype only. Deliberately no network collection, account backend or durable storage. */
const money = n => new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL',maximumFractionDigits:0}).format(n);
const num = n => new Intl.NumberFormat('pt-BR',{maximumFractionDigits:0}).format(n);
const data = [
 {id:1,name:'Um respiro no Belém',street:'Rua ilustrativa · Belém, São Paulo',region:'Belém',price:298000,old:325000,area:48,beds:2,parking:1,fee:420,tax:65,metro:9,source:'QuintoAndar',fit:94,quality:82,discount:12,n:26,confidence:'Média',floor:6,lift:true,photo:true,tag:'QUEDA DE PREÇO',fresh:false,missing:['Face solar não informada','Matrícula e atas do condomínio pendentes'],history:[['19 jul',325000],['20 ago',315000],['19 set',298000]]},
 {id:2,name:'Mais espaço, perto de tudo',street:'Rua ilustrativa · Vila Matilde, São Paulo',region:'Vila Matilde',price:319000,old:319000,area:57,beds:2,parking:1,fee:490,tax:48,metro:12,source:'Loft',fit:89,quality:78,discount:8,n:18,confidence:'Média',floor:4,lift:true,photo:false,tag:'NOVO NO RADAR',fresh:true,missing:['Ruído ainda não avaliado','Estado hidráulico a verificar'],history:[['19 set',319000]]},
 {id:3,name:'A cidade à sua porta',street:'Rua ilustrativa · Bresser–Mooca, São Paulo',region:'Bresser–Mooca',price:285000,old:300000,area:43,beds:2,parking:0,fee:370,tax:null,metro:6,source:'VivaReal',fit:78,quality:null,discount:null,n:4,confidence:'Insuficiente',floor:null,lift:null,photo:false,tag:'DADOS A CONFERIR',fresh:false,missing:['IPTU não informado','Andar e elevador desconhecidos','Sem vaga de garagem'],history:[['10 ago',300000],['19 set',285000]]},
 {id:4,name:'Luz e tranquilidade no Tatuapé',street:'Rua ilustrativa · Tatuapé, São Paulo',region:'Tatuapé',price:348000,old:360000,area:52,beds:2,parking:1,fee:610,tax:80,metro:14,source:'ZAP Imóveis',fit:82,quality:85,discount:5,n:31,confidence:'Média',floor:8,lift:true,photo:false,tag:'QUEDA DE PREÇO',fresh:false,missing:['Reforma da fachada a confirmar'],history:[['12 jul',360000],['19 set',348000]]},
 {id:5,name:'Seu primeiro endereço',street:'Rua ilustrativa · Penha, São Paulo',region:'Penha',price:265000,old:265000,area:41,beds:2,parking:1,fee:330,tax:32,metro:16,source:'Imobiliária parceira',fit:81,quality:74,discount:6,n:15,confidence:'Baixa',floor:2,lift:false,photo:false,tag:'NOVO NO RADAR',fresh:true,missing:['16 minutos até o metrô: acima da meta','Sem elevador'],history:[['19 set',265000]]},
 {id:6,name:'Planta prática, bairro vivo',street:'Rua ilustrativa · Belém, São Paulo',region:'Belém',price:329000,old:329000,area:55,beds:2,parking:1,fee:510,tax:55,metro:11,source:'OLX',fit:88,quality:80,discount:7,n:22,confidence:'Média',floor:5,lift:true,photo:false,tag:'NOVO NO RADAR',fresh:true,missing:['Ventilação dos banheiros a verificar'],history:[['19 set',329000]]}
];
const state={page:'radar',tab:'all',query:'',sort:'fit',view:'list',saved:new Set([1,2]),compare:new Set(),stages:{1:'Salvos',2:'Visita marcada'},notes:{},profile:{budget:330000,minArea:35,beds:2,metro:15,parking:false,weights:{price:40,location:35,quality:25}},filterProfile:false};
const navItems=[['radar','◉','Radar de oportunidades'],['compare','⇆','Comparar imóveis'],['journey','♡','Minha jornada'],['budget','▤','Planejar a compra'],['profile','⚙','Minha busca'],['sources','↻','Fontes e atualização']];
const main=document.querySelector('#main'),dialog=document.querySelector('#detail');
let lastFocus;
function escapeText(value){return String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.style.display='none',3500);}
function go(page){location.hash=page;}
function renderNav(){document.querySelector('#nav').innerHTML=navItems.map(([id,icon,name])=>`<a href="#${id}" class="${state.page===id?'active':''}" ${state.page===id?'aria-current="page"':''}><span class="nav-icon" aria-hidden="true">${icon}</span>${name}${id==='compare'&&state.compare.size?`<span class="nav-count">${state.compare.size}</span>`:''}</a>`).join('');}
function header(title,sub,action=''){return `<div class="heading"><div><p class="eyebrow">ENCONTRE. COMPARE. ESCOLHA BEM.</p><h1>${title}</h1><p class="subtitle">${sub}</p></div>${action}</div>`;}
function photo(p){return `<div class="property-photo">${p.photo?'<img src="assets/apartment-demo.png" alt="Sala de apartamento fictício: imagem ilustrativa gerada por IA">':'<div class="photo-placeholder"><span aria-hidden="true">⌂</span><small>FOTO NÃO DISPONÍVEL</small></div>'}<span class="photo-label">${p.photo?'Imagem ilustrativa · IA':'Anúncio fictício'}</span></div>`;}
function costs(p){return p.tax===null?`${money(p.fee)} + IPTU não informado`:`${money(p.fee+p.tax)}/mês · cond. + IPTU`;}
function card(p){return `<article class="property">${photo(p)}<div class="property-body"><div class="property-title"><div><span class="tag ${p.discount===null?'amber':''}">${p.tag}</span><h3>${p.name}</h3><p>${p.street}</p></div><button class="save ${state.saved.has(p.id)?'saved':''}" data-save="${p.id}" aria-label="${state.saved.has(p.id)?'Remover dos':'Adicionar aos'} salvos: ${p.name}" aria-pressed="${state.saved.has(p.id)}">${state.saved.has(p.id)?'♥':'♡'}</button></div><div class="features"><span>${p.area} m²</span><span>${p.beds} quartos</span><span>${p.parking} vaga${p.parking===1?'':'s'}</span><span>↗ ${p.metro} min do metrô*</span></div><div class="price-line"><div class="price">${money(p.price)}<small>${costs(p)}</small></div><div class="opportunity">${p.discount!==null?`${p.discount}% abaixo dos similares`:'Preço sem estimativa'}<small>${p.discount!==null?`${p.n} comparáveis · confiança ${p.confidence.toLowerCase()}`:`Apenas ${p.n} comparáveis`}</small></div></div><div class="score-line"><span class="score">${p.fit}%</span> aderência ilustrativa <span class="bullet"></span> ${num(p.price/p.area)} R$/m²</div><div class="card-bottom"><span>${p.source} · exemplo</span><label><input type="checkbox" data-compare="${p.id}" ${state.compare.has(p.id)?'checked':''}> Comparar</label><button class="text-button" data-detail="${p.id}">Ver dossiê ↗</button></div></div></article>`;}
function getFiltered(){return data.filter(p=>(state.tab!=='saved'||state.saved.has(p.id))&&(state.tab!=='drops'||p.old>p.price)&&(`${p.name} ${p.region} ${p.source}`.toLocaleLowerCase().includes(state.query.toLocaleLowerCase()))&&(!state.filterProfile||(p.price<=state.profile.budget&&p.area>=state.profile.minArea&&p.beds>=state.profile.beds&&p.metro<=state.profile.metro&&(!state.profile.parking||p.parking>=1)))).sort((a,b)=>state.sort==='price'?a.price-b.price:state.sort==='area'?a.price/a.area-b.price/b.area:b.fit-a.fit);}
function cards(){const list=getFiltered();document.querySelector('#results-count').textContent=`${list.length} apartamentos fictícios ${state.filterProfile?'dentro dos filtros de sua busca':'para explorar'} · *tempos de trajeto simulados`;const root=document.querySelector('#list');root.innerHTML=list.length?list.map(card).join(''):'<div class="empty"><h3>Nenhum imóvel com esses filtros</h3><p>Experimente outro bairro ou desative “Aplicar minha busca”.</p><button data-reset>Limpar filtros</button></div>';bindCards(root);}
function radar(){main.innerHTML=header('Seu próximo lar começa aqui.','Um lugar para acompanhar oportunidades. Uma decisão com mais contexto.','<button id="refresh">↻ Simular atualização</button>')+`<section class="stats" aria-label="Resumo demonstrativo"><div class="stat"><span class="stat-head">NO SEU RADAR</span><b>06</b><span>apartamentos de demonstração</span></div><div class="stat"><span class="stat-head">NOVOS ENDEREÇOS</span><b>03 <span style="display:inline;font-size:16px;color:#88a65e">↗</span></b><span>novidades simuladas hoje</span></div><div class="stat"><span class="stat-head">PREÇO CAIU</span><b>03</b><span>reduções no histórico fictício</span></div><div class="stat"><span class="stat-head">SUA LISTA</span><b>${String(state.saved.size).padStart(2,'0')}</b><span>lugares para olhar com calma</span></div></section><div id="tray"></div><div class="radar-grid"><section><div class="controls"><div class="tabs" role="group" aria-label="Filtrar oportunidades"><button class="tab ${state.tab==='all'?'active':''}" data-tab="all">Todos</button><button class="tab ${state.tab==='drops'?'active':''}" data-tab="drops">Preço caiu</button><button class="tab ${state.tab==='saved'?'active':''}" data-tab="saved">Salvos</button></div><div class="view-toggle" role="group" aria-label="Layout"><button data-view="list" class="${state.view==='list'?'active':''}">Lista</button><button data-view="map" class="${state.view==='map'?'active':''}">Mapa</button></div></div><div class="filter-line"><input id="search" type="search" placeholder="Busque por bairro ou fonte…" aria-label="Buscar bairro ou fonte" value="${escapeText(state.query)}"><select id="sort" aria-label="Ordenar imóveis"><option value="fit">Maior aderência</option><option value="price">Menor preço</option><option value="area">Menor preço por m²</option></select></div><label class="small" style="display:flex;gap:7px;align-items:center;margin-bottom:15px"><input type="checkbox" id="filter-profile" ${state.filterProfile?'checked':''}> Aplicar minha busca · até ${money(state.profile.budget)}</label><p class="listing-count" id="results-count"></p><div class="${state.view==='map'?'map-layout':''}"><div id="list"></div>${state.view==='map'?map():''}</div></section><aside class="rail"><div class="daily"><p class="eyebrow">SEU RESUMO DO DIA</p><span class="date">19 de setembro · cenário demonstrativo</span><h2>A oportunidade também está na mudança.</h2><p>O exemplo do Belém caiu ${money(27000)} desde julho. Compare o preço e confira as pendências antes de avançar.</p><button data-detail="1">Explorar essa mudança ↗</button></div><div class="panel"><h3>Uma busca com a sua cara</h3><div class="check-row"><span>Orçamento</span><b>Até ${money(state.profile.budget)}</b></div><div class="check-row"><span>Área mínima</span><b>${state.profile.minArea} m²</b></div><div class="check-row"><span>Quartos</span><b>${state.profile.beds} ou mais</b></div><div class="check-row"><span>Metrô a pé</span><b>Até ${state.profile.metro} min</b></div><button class="text-button" data-go="profile" style="margin-top:14px;font-size:11px">Editar minhas preferências →</button></div><div class="subtle"><b>Preço bom precisa de evidência.</b><br>Comparamos imóveis semelhantes e mostramos o tamanho da amostra. Poucos dados? A estimativa fica pendente.</div></aside></div>`;
document.querySelector('#sort').value=state.sort;document.querySelector('#sort').onchange=e=>{state.sort=e.target.value;cards();};document.querySelector('#search').oninput=e=>{state.query=e.target.value;cards();};document.querySelector('#filter-profile').onchange=e=>{state.filterProfile=e.target.checked;cards();};document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{state.tab=b.dataset.tab;radar();});document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{state.view=b.dataset.view;radar();});document.querySelector('#refresh').onclick=()=>toast('Simulação concluída. Nenhum portal foi consultado.');cards();tray();bindCommon(main);}
function map(){return `<div class="map-canvas" aria-label="Esquema ilustrativo de bairros, sem precisão geográfica"><svg viewBox="0 0 400 650" preserveAspectRatio="none" aria-hidden="true"><path d="M-20 180L450 370M10 -10L380 700M-30 470L420 110M120 -20L-30 700M320 -10L260 700" stroke="#fafbf6" stroke-width="22" fill="none"/><path d="M-10 620Q120 390 240 380T450 240" stroke="#bdcdb2" stroke-width="32" fill="none"/><path d="M-10 620Q120 390 240 380T450 240" stroke="#dce8d5" stroke-width="22" fill="none"/><path d="M20 120L160 260L320 290L420 410" stroke="#c97763" stroke-width="4" stroke-dasharray="8 5" fill="none"/></svg><button class="map-pin" data-detail="1">Belém · R$ 298 mil</button><button class="map-pin" data-detail="4">Tatuapé · R$ 348 mil</button><button class="map-pin" data-detail="3">Mooca · R$ 285 mil</button><div class="map-label"><b>Alternativa de layout: mapa + lista</b><br>Esquema de navegação; posições fictícias e independentes dos filtros. Mapa real depende de geocodificação.</div></div>`;}
function tray(){const el=document.querySelector('#tray');if(!el)return;el.innerHTML=state.compare.size?`<div class="comparison-tray"><span><b>${state.compare.size} de 4</b> imóveis selecionados</span><button class="primary" data-go="compare">Abrir comparador →</button></div>`:'';bindCommon(el);}
function bindCommon(root){root.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));root.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>detail(Number(b.dataset.detail)));}
function bindCards(root){bindCommon(root);root.querySelectorAll('[data-save]').forEach(b=>b.onclick=()=>{const id=Number(b.dataset.save);if(state.saved.has(id)){state.saved.delete(id);}else{state.saved.add(id);state.stages[id]??='Salvos';}radar();renderNav();});root.querySelectorAll('[data-compare]').forEach(c=>c.onchange=()=>{const id=Number(c.dataset.compare);if(c.checked&&state.compare.size>=4){c.checked=false;toast('Compare até quatro imóveis por vez.');return;}c.checked?state.compare.add(id):state.compare.delete(id);tray();renderNav();});root.querySelectorAll('[data-reset]').forEach(b=>b.onclick=()=>{state.query='';state.tab='all';state.filterProfile=false;radar();});}
function detail(id){const p=data.find(p=>p.id===id);lastFocus=document.activeElement;document.querySelector('#detail-content').innerHTML=`<div class="dialog-header"><div><p class="eyebrow">DOSSIÊ DO IMÓVEL · EXEMPLO</p><h2>${p.name}</h2></div><button id="close-dialog" aria-label="Fechar dossiê">×</button></div><div class="detail-grid"><div>${photo(p)}<span class="tag">${p.source} · dados fictícios</span><p class="subtitle" style="margin-top:10px">${p.street}</p><div class="features"><span>${p.area} m²</span><span>${p.beds} quartos</span><span>${p.parking} vaga(s)</span><span>${p.floor===null?'Andar desconhecido':p.floor+'º andar'}</span></div><div class="panel"><h3>A história do preço</h3>${p.history.length>1?`<svg class="chart" viewBox="0 0 400 130" role="img" aria-label="Trajetória ilustrativa de redução de preço"><path d="M10 105H390M10 55H390" stroke="#e7ecdf" stroke-dasharray="4 4"/><path d="M20 25L190 58L375 103" stroke="#558765" stroke-width="3" fill="none"/><circle cx="20" cy="25" r="5" fill="#558765"/><circle cx="375" cy="103" r="5" fill="#558765"/></svg>`:'<p>Primeira observação: ainda não há histórico suficiente.</p>'}<div class="timeline">${p.history.map(([date,price])=>`<div><span>${date} · exemplo</span><b>${money(price)}</b></div>`).join('')}</div></div><div class="panel"><h3>Antes de se apaixonar, confira</h3><ul>${p.missing.map(m=>`<li>${m}</li>`).join('')}</ul><p>Informações documentais, estruturais e de vizinhança devem ser confirmadas. Ausência de dado não significa ausência de problema.</p></div></div><div><div class="price" style="font-size:32px">${money(p.price)}</div><p class="subtitle">${num(p.price/p.area)} R$/m² · preço anunciado fictício</p><div class="check-row"><span>Condomínio mensal</span><b>${money(p.fee)}</b></div><div class="check-row"><span>IPTU mensal equivalente</span><b>${p.tax===null?'Não informado':money(p.tax)}</b></div><div class="panel" style="margin-top:22px"><span class="eyebrow">OPORTUNIDADE DE PREÇO</span><h2 style="margin-top:12px">${p.discount!==null?p.discount+'% abaixo dos similares':'Amostra insuficiente'}</h2><p>${p.n} comparáveis fictícios · confiança ${p.confidence.toLowerCase()}.</p><p class="explain">${p.discount!==null?'Na implementação, mediana de anúncios únicos, recentes e semelhantes na região, excluindo este imóvel. Tamanho, vagas, tipologia e distância serão considerados.':'Sem desconto estimado: quatro anúncios não sustentam uma conclusão confiável.'}</p><details><summary class="small">Como interpretar a comparação</summary><p>Os valores deste protótipo são exemplos definidos para revisar a interface. O modelo real deverá mostrar cada comparável, critérios, período, dispersão e fontes. Preço pedido não é preço efetivamente negociado.</p></details></div><div class="panel"><div class="score-large">${p.fit}% <small>aderência ilustrativa</small></div><p>A afinidade com você é diferente da qualidade observável.</p><div class="quality-row"><span>Qualidade observável</span><b>${p.quality===null?'Pendente':p.quality+'/100'}</b></div>${p.quality!==null?`<div class="meter"><span style="width:${p.quality}%"></span></div>`:''}<div class="quality-row"><span>Dados importantes ausentes</span><b>${p.missing.length}</b></div><p class="explain">Notas ilustrativas. O produto calculará fatores explicáveis; informação ausente fica pendente, nunca recebe nota máxima.</p></div><div class="detail-actions"><button class="primary" id="detail-save">${state.saved.has(p.id)?'Salvo na minha jornada':'Salvar na minha jornada'}</button><button id="detail-compare">${state.compare.has(p.id)?'Remover da comparação':'Comparar'}</button></div><p class="insight">Na versão conectada: link original, galeria real, data da coleta e fontes por campo.</p></div></div>`;document.querySelector('#close-dialog').onclick=()=>dialog.close();document.querySelector('#detail-save').onclick=()=>{state.saved.add(id);state.stages[id]??='Salvos';document.querySelector('#detail-save').textContent='Salvo na minha jornada';toast('Imóvel salvo nesta sessão de demonstração.');};document.querySelector('#detail-compare').onclick=()=>{if(state.compare.has(id))state.compare.delete(id);else if(state.compare.size<4)state.compare.add(id);else{toast('Limite de quatro imóveis.');return;}document.querySelector('#detail-compare').textContent=state.compare.has(id)?'Remover da comparação':'Comparar';renderNav();};dialog.showModal();}
dialog.addEventListener('close',()=>{const id=lastFocus?.dataset?.detail;render();const target=id?main.querySelector('[data-detail="'+id+'"]'):null;(target||main).focus({preventScroll:true});});
function comparison(){const list=data.filter(p=>state.compare.has(p.id));main.innerHTML=header('Lado a lado. Sem adivinhação.','Compare custo, encaixe e aquilo que ainda precisa ser confirmado.','<button data-go="radar">Escolher imóveis</button>')+(list.length<2?`<div class="empty"><h2>Escolha pelo menos dois apartamentos</h2><p>Marque “Comparar” nos anúncios. Você pode comparar até quatro.</p><button class="primary" data-go="radar">Explorar oportunidades →</button></div>`:`<div class="table-wrap"><table><caption>Comparação demonstrativa · preços pedidos e notas fictícias</caption><thead><tr><th>O que importa</th>${list.map(p=>`<th>${p.name}<p class="muted small">${p.region}</p><button class="text-button" data-remove="${p.id}" aria-label="Remover ${p.name} da comparação">Remover ×</button></th>`).join('')}</tr></thead><tbody>${[['Preço pedido',p=>`<b>${money(p.price)}</b>`],['Preço por m²',p=>money(p.price/p.area)],['Área privativa',p=>p.area+' m²'],['Quartos / vagas',p=>p.beds+' quartos · '+p.parking+' vaga(s)'],['Condomínio + IPTU',p=>costs(p)],['Até o metrô',p=>p.metro+' min · simulado'],['Preço vs. similares',p=>p.discount!==null?`${p.discount}% abaixo`:'Sem estimativa'],['Confiança / amostra',p=>`${p.confidence} · ${p.n} exemplos`],['Aderência ilustrativa',p=>p.fit+'%'],['Qualidade ilustrativa',p=>p.quality===null?'Pendente':p.quality+'/100'],['Pendências',p=>p.missing.join('<br>')],['Próximo passo',p=>`<button data-detail="${p.id}">Abrir dossiê</button>`]].map(([name,f])=>`<tr><td><b>${name}</b></td>${list.map(p=>`<td>${f(p)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="review-note">Um preço menor pode esconder despesas, reforma ou dados ausentes. Use a comparação para decidir o que investigar, não para substituir uma avaliação.</p>`);bindCommon(main);main.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{state.compare.delete(Number(b.dataset.remove));render();});}
function profile(){const p=state.profile;main.innerHTML=header('Uma boa casa. Para a sua vida.','Defina o que é indispensável e o que pode ser negociado.')+`<form id="profile-form"><div class="form-grid"><section class="panel"><h2>Os seus limites</h2><p>Estes critérios filtram os exemplos do radar.</p><div class="form-field"><label for="p-budget">Preço máximo do imóvel (R$)</label><input id="p-budget" name="budget" type="number" min="50000" max="50000000" step="1000" value="${p.budget}" required><small>O custo de aquisição e a reserva são planejados separadamente.</small></div><div class="form-field"><label for="p-area">Área mínima (m²)</label><input id="p-area" name="minArea" type="number" min="10" max="1000" value="${p.minArea}" required></div><div class="form-field"><label for="p-beds">Mínimo de quartos</label><select id="p-beds" name="beds"><option value="1">1 quarto</option><option value="2">2 quartos</option><option value="3">3 quartos</option></select></div><div class="form-field"><label for="p-metro">Tempo máximo a pé até o metrô (min)</label><input id="p-metro" name="metro" type="number" min="1" max="120" value="${p.metro}" required></div><div class="checks"><label><input name="parking" type="checkbox" ${p.parking?'checked':''}> Pelo menos uma vaga é indispensável</label></div></section><section><div class="panel"><h2>O que pesa na sua escolha?</h2><p>Explore prioridades. Nesta versão os pesos ficam na sessão, mas as notas dos anúncios continuam ilustrativas.</p>${[['price','Preço e custo'],['location','Localização'],['quality','Qualidade']].map(([k,label])=>`<div class="weight"><label for="w-${k}">${label}</label><input id="w-${k}" name="${k}" type="range" min="0" max="100" value="${p.weights[k]}"><output for="w-${k}">${p.weights[k]}</output></div>`).join('')}<p class="subtle">Pesos são relativos e serão normalizados. O padrão de qualidade e a confiança dos dados continuam visíveis para todos.</p></div><div class="panel"><h3>Seu perfil vai além do preço</h3><p>Na implementação: bairros e áreas desenhadas no mapa, destinos de rotina, acessibilidade, elevador, sol, silêncio, varanda, pets e teto de condomínio.</p><p>Critérios sem informação devem aparecer como “a confirmar”, nunca como atendidos.</p></div></section></div><div class="form-actions"><button class="primary" type="submit">Aplicar busca no radar →</button><span class="muted">Demonstração: sem conta real ou salvamento permanente.</span></div></form>`;document.querySelector('#p-beds').value=p.beds;main.querySelectorAll('input[type=range]').forEach(i=>i.oninput=()=>i.nextElementSibling.value=i.value);document.querySelector('#profile-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);state.profile={budget:+f.get('budget'),minArea:+f.get('minArea'),beds:+f.get('beds'),metro:+f.get('metro'),parking:f.has('parking'),weights:{price:+f.get('price'),location:+f.get('location'),quality:+f.get('quality')}};state.filterProfile=true;state.query='';state.tab='all';go('radar');toast('Filtros aplicados nesta sessão. Notas continuam ilustrativas.');};}
function journey(){main.innerHTML=header('Da descoberta à chave na mão.','Guarde suas impressões e acompanhe cada próximo passo.','<button data-go="radar">Adicionar imóvel</button>')+`<div class="board">${['Salvos','Visita marcada','Avaliado'].map(stage=>`<section class="board-col"><h2>${stage} <span class="muted">${data.filter(p=>state.saved.has(p.id)&&state.stages[p.id]===stage).length}</span></h2>${data.filter(p=>state.saved.has(p.id)&&state.stages[p.id]===stage).map(p=>`<article class="journey-card"><h3>${p.name}</h3><p>${money(p.price)} · ${p.region}</p><button class="text-button" data-detail="${p.id}" style="font-size:11px;margin-bottom:15px">Consultar dossiê ↗</button><label class="small" for="stage-${p.id}">Etapa</label><select id="stage-${p.id}" data-stage="${p.id}" style="margin-top:6px">${['Salvos','Visita marcada','Avaliado'].map(s=>`<option ${s===stage?'selected':''}>${s}</option>`).join('')}</select><label class="small" for="note-${p.id}" style="display:block;margin-top:12px">Impressões e perguntas para a visita</label><textarea id="note-${p.id}" data-note="${p.id}" placeholder="Ex.: conferir ruído com a janela aberta…">${escapeText(state.notes[p.id]||'')}</textarea></article>`).join('')||'<p class="small muted">Os imóveis nesta etapa aparecerão aqui.</p>'}</section>`).join('')}</div><p class="review-note">As anotações ficam apenas nesta sessão. O produto terá datas de visita, tarefas, documentos, propostas e histórico privado por usuário.</p>`;bindCommon(main);main.querySelectorAll('[data-stage]').forEach(s=>s.onchange=()=>{state.stages[s.dataset.stage]=s.value;journey();toast('Etapa alterada nesta sessão.');});main.querySelectorAll('[data-note]').forEach(t=>t.oninput=()=>state.notes[t.dataset.note]=t.value);}
function budget(){main.innerHTML=header('O preço é só o começo.','Explore a entrada, o financiamento e o custo de manter seu novo lar.')+`<div class="form-grid"><form class="panel" id="budget-form"><h2>Monte um cenário</h2>${[['value','Valor do imóvel (R$)',298000,50000,50000000],['down','Entrada (R$)',140000,0,50000000],['rate','Taxa efetiva anual (%)',11,0,50],['months','Prazo (meses)',240,12,480],['monthly','Condomínio + IPTU mensal (R$)',485,0,100000],['fees','Despesas de aquisição estimadas (R$)',12000,0,5000000],['reserve','Reforma e reserva (R$)',20000,0,5000000]].map(([id,label,value,min,max])=>`<div class="form-field"><label for="b-${id}">${label}</label><input id="b-${id}" name="${id}" type="number" step="${id==='rate'?'.1':'1'}" value="${value}" min="${min}" max="${max}" required></div>`).join('')}<div class="form-field"><label for="b-model">Amortização</label><select id="b-model" name="model"><option value="price">Price · parcela base constante</option><option value="sac">SAC · amortização constante</option></select></div><button type="submit" class="primary">Calcular cenário</button></form><section><div class="budget-result" id="budget-result" aria-live="polite"></div><div class="panel" style="margin-top:20px"><h3>Uma simulação para enxergar o todo</h3><p>A taxa é hipotética. Cálculo sem TR, seguros, tarifas bancárias, inflação ou atualização de condomínio. As despesas de aquisição são preenchidas por você.</p><p>O resultado não é CET nem proposta de crédito. Compare propostas bancárias antes de contratar.</p></div></section></div>`;document.querySelector('#budget-form').onsubmit=e=>{e.preventDefault();calculateBudget();};calculateBudget();}
function calculateBudget(){const form=document.querySelector('#budget-form');if(!form.reportValidity())return;const f=new FormData(form),value=+f.get('value'),down=+f.get('down'),n=+f.get('months'),r=Math.pow(1+(+f.get('rate'))/100,1/12)-1,principal=value-down,monthly=+f.get('monthly');if(principal<0){document.querySelector('#budget-result').innerHTML='<h2>Revise a entrada</h2><p>A entrada não pode ser maior que o preço do imóvel.</p>';return;}const sac=f.get('model')==='sac',payment=sac?principal/n+principal*r:(r===0?principal/n:principal*r/(1-Math.pow(1+r,-n))),interest=sac?principal*r*(n+1)/2:payment*n-principal;document.querySelector('#budget-result').innerHTML=`<p class="eyebrow" style="color:#d1dec4">CENÁRIO HIPOTÉTICO · ${sac?'SAC':'PRICE'}</p><h2>${sac?'Primeiro mês':'Parcela base + moradia'}</h2><div class="price">${money(payment+monthly)}<span style="font-size:14px;font-weight:400"> /mês</span></div><div class="check-row"><span>Parcela ${sac?'inicial':'base'}</span><b>${money(payment)}</b></div><div class="check-row"><span>Condomínio + IPTU</span><b>${money(monthly)}</b></div><div class="check-row"><span>Valor financiado</span><b>${money(principal)}</b></div><div class="check-row"><span>Juros estimados no prazo</span><b>${money(interest)}</b></div><div class="check-row"><span>Entrada + despesas + reserva</span><b>${money(down+(+f.get('fees'))+(+f.get('reserve')))}</b></div><p>Taxa mensal equivalente: ${(r*100).toFixed(3).replace('.',',')}%. ${sac?'As parcelas diminuem com a amortização.':'A parcela base fica constante sob estas hipóteses.'} Valores arredondados para exibição.</p>`;}
function sources(){const sources=[['Q','QuintoAndar','Autorização a validar','https://www.quintoandar.com.br','Portal presente no script original. Conector legado ainda não validado.'],['L','Loft','Autorização a validar','https://loft.com.br','Portal presente no script original. Endpoint interno não garante integração estável.'],['Z','ZAP Imóveis','Integração planejada','https://www.zapimoveis.com.br','Feed de publicação não equivale a acesso ao catálogo.'],['V','VivaReal','Integração planejada','https://www.vivareal.com.br','Integração condicionada a acesso autorizado e contrato de dados.'],['O','OLX','Integração planejada','https://www.olx.com.br/imoveis','Importação ou integração autorizada; sem coleta ativa neste protótipo.'],['I','Imobiliárias e arquivos','Importação planejada',null,'Planilhas e feeds autorizados, com prévia, validação e origem por registro.']];main.innerHTML=header('Dados bons também têm histórico.','Saiba de onde veio cada informação e quando ela foi realmente verificada.')+`<div class="subtle" style="margin-bottom:24px"><b>Nenhuma fonte conectada neste protótipo.</b> As marcas indicam o escopo proposto, não integrações funcionando. No produto, falhas e bloqueios preservam o último snapshot válido e aparecem no radar.</div><div class="source-grid">${sources.map(([mark,name,status,url,desc])=>`<article class="panel"><div class="source-logo">${mark}</div><h2 style="font-size:17px">${name}</h2><span class="tag amber">${status}</span><p>${desc}</p><div class="check-row"><span>Último sucesso</span><b>Nunca</b></div><div class="check-row"><span>Cobertura real</span><b>Não verificada</b></div>${url?`<p><a href="${url}" target="_blank" rel="noopener noreferrer">Abrir portal original ↗</a></p>`:'<p>CSV, XLSX e feeds estruturados.</p>'}</article>`).join('')}</div><div class="form-grid" style="margin-top:24px"><section class="panel"><h3>Rotina diária prevista</h3><p>Coleta programada, comparação com o histórico, atualização do ranking e resumo das mudanças. Horário e fuso configuráveis, sem sobreposição de execuções.</p></section><section class="panel"><h3>Contexto além dos anúncios</h3><p>GeoSampa, mobilidade e indicadores agregados de preços poderão enriquecer a análise. Cada camada mostrará fonte, cobertura e data.</p></section></div>`;}
function render(){renderNav();({radar,compare:comparison,journey,budget,profile,sources}[state.page]||radar)();}
window.addEventListener('hashchange',()=>{state.page=navItems.some(n=>n[0]===location.hash.slice(1))?location.hash.slice(1):'radar';render();window.scrollTo(0,0);main.focus({preventScroll:true});});document.querySelector('#profile-shortcut').onclick=()=>go('profile');state.page=navItems.some(n=>n[0]===location.hash.slice(1))?location.hash.slice(1):'radar';render();
